-- A57: batch b001_fr, chunk 4 (25 videos for learners of fr). Guarded: nothing is written when a row of
-- this chunk exists already (the whole transaction stops); English (media_exercise_sets) is not touched.
begin;
do $g$ begin
  if exists (select 1 from public.media_exercise_sets_l10n where learning_language = 'fr' and media_id in (288,242,868,4015,291,5108,5660,807,277,571,4365,121,5069,4788,5129,358,819,741,690,225,92,7809,731,800,558)) then
    raise exception 'A57 out/b001_fr_04.sql: rows exist already - nothing written';
  end if;
end $g$;
do $g$ begin
  if (select count(*) from public.media_exercise_sets_l10n where learning_language = 'fr' and media_id in (288,242,868,4015,291,5108,5660,807,277,571,4365,121,5069,4788,5129,358,819,741,690,225,92,7809,731,800,558)) <> 25 then
    raise exception 'A57 out/b001_fr_04.sql: not 25 rows after the insert';
  end if;
end $g$;
commit;
